  "test": "import logging

import pytest
from mcp.server.mcpserver.utilities.func_metadata import _inline_root_ref


def test_inline_root_ref_success():
    schema = {
        "$ref": "#/$defs/Model",
        "$defs": {
            "Model": {
                "type": "object",
                "properties": {"x": {"type": "integer"}},
                "required": ["x"],
            }
        },
        "title": "Ignored",
    }
    result = _inline_root_ref(schema)
    # The root should be the inlined definition without $ref, preserving other siblings
    assert result == {
        "type": "object",
        "properties": {"x": {"type": "integer"}},
        "required": ["x"],
        "title": "Ignored",
    }


def test_inline_root_ref_missing_defs_logs_warning(caplog):
    schema = {"$ref": "#/$defs/Model"}
    caplog.set_level(logging.WARNING)
    result = _inline_root_ref(schema)
    # Should return the original schema unchanged
    assert result == schema
    # A warning should have been emitted
    assert any("$ref #/$defs/Model" in record.getMessage() and "$defs" in record.getMessage() for record in caplog.records)
